export const REQUEST_ID_HEADER = 'x-request-id';
/** Stack PUT/POST/DELETE success bodies also carry `requestId`; error bodies do not. */
export function getRequestId(response, body) {
    const fromHeader = response?.headers.get(REQUEST_ID_HEADER);
    if (fromHeader)
        return fromHeader;
    if (body && typeof body === 'object' && 'requestId' in body) {
        const fromBody = body.requestId;
        if (typeof fromBody === 'string' && fromBody)
            return fromBody;
    }
    return undefined;
}
export function withRequestId(message, requestId) {
    if (!requestId)
        return message;
    const suffix = `(request ID ${requestId})`;
    return message.endsWith('.') ? `${message.slice(0, -1)} ${suffix}.` : `${message} ${suffix}`;
}
